  --editorBgColor: #f7f5eb;
  --editorColor: #28372e;
  --editorColor80: #47574c;
  --editorColor60: #596a5c;
  --editorColor50: #657668;
  --editorColor40: #829183;
  --editorColor30: #a2ada1;
  --editorColor10: #dee3d6;
  --editorColor04: #eff0e6;
  --themeColor: #3c674f;
  --themeColor90: #487158;
  --themeColor80: #527962;
  --themeColor70: #60836d;
  --themeColor60: #6f8f78;
  --themeColor50: #829d87;
  --themeColor40: #96ad97;
  --themeColor30: #adc1ac;
  --themeColor20: #c2d3bd;
  --themeColor10: #e1eadb;
  --highlightColor: #f3e5bf;
  --highlightThemeColor: #4a755c;
  --selectionColor: #d6e5d3;
  --deleteColor: #a04234;
  --iconColor: #607466;
  --focusColor: #3c674f;
  --sideBarBgColor: #eaeee3;
  --sideBarColor: #45594a;
  --sideBarTitleColor: #284b39;
  --sideBarTextColor: #556a59;
  --sideBarIconColor: #4c6654;
  --sideBarBorderColor: #d6ded0;
  --sideBarItemHoverBgColor: #e0e7da;
  --sideBarItemActiveBgColor: #d6e4d3;
  --itemBgColor: #e1e7d9;
  --titleBarBgColor: #f0f1e7;
  --floatBgColor: #fbfaf2;
  --floatFontColor: #36483c;
  --floatBorderColor: #d5ddd0;
  --floatHoverColor: #e7eddf;
  --inputBgColor: #fbfaf2;
  --buttonBgColor: #eaece1;
  --buttonBgColorHover: #e0e6d9;
  --buttonPrimaryBgColor: #3c674f;
  --buttonPrimaryBgColorHover: #315641;
  --buttonPrimaryBgColorActive: #284b39;
  --buttonPrimaryFontColor: #fffef7;
  --linkColor: #2e654b;
  --proseAccent: #3c674f;
  --headingColor: #284b39;
  --h1Color: #244636;
  --h2Color: #2e5743;
  --h3Color: #795038;
  --h4Color: #455f50;
  --h5Color: #455f50;
  --h6Color: #566859;
  --emColor: #76462f;
  --strongColor: #253c30;
  --listMarkerColor: #4d755b;
  --blockquoteTextColor: #3f5a49;
  --blockquoteBorderColor: #74927a;
  --tableBorderColor: #d1dbcb;
  --hrColor: #cdd8c8;
  --codeBgColor: #e8ede1;
  --codeBlockBgColor: #e9eee4;
  --codeBlockColor: #314a3a;
  --footnoteBgColor: #e8ede1;
}

.mu-container h1:is(.mu-atx-heading, .mu-setext-heading) {
  text-align: start;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.mu-container h2:is(.mu-atx-heading, .mu-setext-heading) {
  padding-block-end: 0.3em;
  border-block-end: 1px solid var(--hrColor);
}

.mu-container .mu-block-quote {
  background: #eff2e7;
  border-radius: 0 6px 6px 0;
  padding-block: 0.25rem;
}

.mu-container th {
  background: #e5ecdf;
  color: #294b3a;
}

.mu-container tbody tr:nth-child(even) {
  background: #f1f3e9;
}

.mu-container .token:is(.comment, .prolog, .doctype) {
  color: #586b5a;
}

.mu-container .token:is(.string, .char, .attr-value) {
  color: #356648;
}

.mu-container .token:is(.keyword, .operator, .boolean, .property) {
  color: #825335;
}

.mu-container .token:is(.function, .number, .constant) {
  color: #406078;
}

.source-code .CodeMirror {
  background-color: #f4f4e9;
  color: #293c30;
}

.source-code .CodeMirror-gutters {
  background-color: #ebefe3;
  border-inline-end-color: #d5dece;
}
